def effective_limit(value, default=10):
    if value is None:
        return default
    elif value == 0:
        return 0
    elif isinstance(value, int) and value > 0:
        return value
    else:
        raise ValueError("Invalid value for effective_limit. Must be None (default), zero (disabled), or a positive integer.")

import settings
import pytest

def test_effective_limit_none():
    assert settings.effective_limit(None) == 10

def test_effective_limit_zero():
    assert settings.effective_limit(0) == 0

def test_effective_limit_positive():
    assert settings.effective_limit(5) == 5
    assert settings.effective_limit(100) == 100

def test_effective_limit_negative_raises():
    with pytest.raises(ValueError):
        settings.effective_limit(-1)

def test_effective_limit_non_int_raises():
    with pytest.raises(ValueError):
        settings.effective_limit("invalid")

def test_effective_limit_custom_default():
